sys_script.script:
(function executeRule(current, previous) {

    // ─────────────────────────────────────────────
    // Score-Reason pairs to validate.
    // Each entry: [scoreField, reasonField, categoryLabel]
    // ─────────────────────────────────────────────
    var pairs = [
        ['quality_score',       'quality_reason',       'Quality'],
        ['delivery_score',      'delivery_reason',      'Delivery'],
        ['quantity_score',      'quantity_reason',       'Quantity'],
        ['cost_score',          'cost_reason',           'Cost'],
        ['documentation_score', 'documentation_reason',  'Documentation'],
        ['overall_score',       'overall_reason',        'Overall']
    ];

    var status = current.getValue('evaluation_status');
    var errors = [];

    for (var i = 0; i < pairs.length; i++) {
        var scoreField  = pairs[i][0];
        var reasonField = pairs[i][1];
        var label       = pairs[i][2];

        var scoreVal = current.getValue(scoreField);
        var reasonVal = (current.getValue(reasonField) || '').trim();

        // ───────────────────────────────────
        // RULE 1: Scores must be 0–10
        // (applies regardless of status)
        // ───────────────────────────────────
        if (scoreVal !== null && scoreVal !== '') {
            var num = parseFloat(scoreVal);
            if (isNaN(num) || num < 0 || num > 10) {
                errors.push(label + ' Score must be between 0 and 10 (got ' + scoreVal + ').');
            }
        }

        // ───────────────────────────────────
        // RULE 2: Completed evaluations MUST have
        // both a score AND a reason for every category.
        // ───────────────────────────────────
        if (status === 'completed') {
            if (scoreVal === null || scoreVal === '') {
                errors.push(label + ' Score is required for a completed evaluation.');
            }
            if (!reasonVal) {
                errors.push(label + ' Rating Reason is required for a completed evaluation.');
            }
        }

        // ───────────────────────────────────
        // RULE 3: If a score is provided,
        // the reason must also be provided
        // (even in draft status).
        // ───────────────────────────────────
        if (scoreVal !== null && scoreVal !== '' && !reasonVal) {
            errors.push(label + ' Score is ' + scoreVal + ' but no ' + label + ' Rating Reason was provided. Every score must have a justification.');
        }
    }

    // ───────────────────────────────────
    // Abort if any errors
    // ───────────────────────────────────
    if (errors.length > 0) {
        for (var e = 0; e < errors.length; e++) {
            gs.addErrorMessage(errors[e]);
        }
        current.setAbortAction(true);
    }

})(current, previous);
